create extension if not exists pgcrypto;create extension if not exists pg_trgm;create extension if not exists citext;
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade,role text not null default 'customer' check(role in('customer','admin')),created_at timestamptz default now());
create table if not exists admin_users(user_id uuid primary key references auth.users(id) on delete cascade);
create table if not exists store_settings(id uuid primary key default gen_random_uuid(),is_singleton boolean unique not null default true,name text not null default 'Store',description text,logo_url text,favicon_url text,primary_color text default '#00ff88',secondary_color text default '#07110d',accent_color text default '#fff',currency text default 'INR',support_email citext,support_phone text,address text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists categories(id uuid primary key default gen_random_uuid(),name text unique not null,is_active boolean default true);
create table if not exists products(id uuid primary key default gen_random_uuid(),category_id uuid references categories(id),name text not null,description text,price numeric(12,2) not null check(price>=0),stock int not null default 0 check(stock>=0),image_url text,is_active boolean default true,created_at timestamptz default now());
create table if not exists cart(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,product_id uuid references products(id),quantity int not null check(quantity>0),unique(user_id,product_id));
create table if not exists wishlist(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,product_id uuid references products(id),unique(user_id,product_id));
create table if not exists addresses(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,name text not null,phone text not null,address text not null,city text,state text,pincode text,country text default 'India');
create table if not exists orders(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id),status text default 'pending',payment_status text default 'pending',razorpay_order_id text unique,subtotal numeric(12,2) default 0,shipping numeric(12,2) default 0,total numeric(12,2) default 0,created_at timestamptz default now());
create table if not exists order_items(id uuid primary key default gen_random_uuid(),order_id uuid references orders(id) on delete cascade,product_id uuid references products(id),quantity int not null check(quantity>0),unit_price numeric(12,2) not null);
create table if not exists payments(id uuid primary key default gen_random_uuid(),order_id uuid references orders(id) on delete cascade,razorpay_payment_id text,razorpay_order_id text,amount numeric(12,2),status text default 'created',created_at timestamptz default now());
create table if not exists reviews(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,product_id uuid references products(id) on delete cascade,rating int check(rating between 1 and 5),comment text,created_at timestamptz default now());
create or replace function is_admin() returns boolean language sql security definer stable as $$select exists(select 1 from admin_users where user_id=auth.uid()) or exists(select 1 from profiles where id=auth.uid() and role='admin')$$;
alter table profiles enable row level security;alter table admin_users enable row level security;alter table store_settings enable row level security;alter table categories enable row level security;alter table products enable row level security;alter table cart enable row level security;alter table wishlist enable row level security;alter table addresses enable row level security;alter table orders enable row level security;alter table order_items enable row level security;alter table payments enable row level security;alter table reviews enable row level security;
create policy settings_read on store_settings for select using(true);create policy category_read on categories for select using(is_active);create policy product_read on products for select using(is_active);
create policy cart_own on cart for all using(user_id=auth.uid()) with check(user_id=auth.uid());create policy wish_own on wishlist for all using(user_id=auth.uid()) with check(user_id=auth.uid());create policy address_own on addresses for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy order_read on orders for select using(user_id=auth.uid() or is_admin());create policy order_insert on orders for insert with check(user_id=auth.uid() and payment_status='pending');create policy order_admin on orders for all using(is_admin()) with check(is_admin() and payment_status<>'paid');
create policy items_read on order_items for select using(exists(select 1 from orders where orders.id=order_id and (orders.user_id=auth.uid() or is_admin())));create policy payments_read on payments for select using(exists(select 1 from orders where orders.id=order_id and (orders.user_id=auth.uid() or is_admin())));
create policy reviews_own on reviews for all using(user_id=auth.uid() or is_admin()) with check(user_id=auth.uid() or is_admin());create policy settings_admin on store_settings for all using(is_admin()) with check(is_admin());
